window.HB_TR["1-corinthians"]["ur"]=["1۔ پولس، خدا کی مرضی سے یسوع مسیح کا رسول بننے کے لیے بلایا گیا، اور سوستھینس [ہمارا} بھائی،\n2۔ خدا کے اس کلیسیا کے لیے جو کرنتھ میں ہے، ان لوگوں کے لیے جو مسیح یسوع میں مقدس ہیں، جنہیں مقدس بننے کے لیے بلایا گیا ہے، ان سب کے ساتھ جو ہر جگہ یسوع مسیح ہمارے رب کے نام کو پکارتے ہیں، ان کے اور ہمارے دونوں لیے:\n3. آپ پر فضل اور امن ہو، خدا ہمارے باپ کی طرف سے، اور خداوند یسوع مسیح کی طرف سے۔\n4. میں ہمیشہ آپ کی طرف سے اپنے خدا کا شکر ادا کرتا ہوں، خدا کے فضل کے لیے جو آپ کو یسوع مسیح نے دیا ہے؛\n5۔ کہ ہر چیز میں تم اس سے مالا مال ہو، ہر اظہار میں، اور تمام علم میں؛\n6۔ جیسے مسیح کی گواہی تم میں تصدیق ہوئی:\n7۔ تاکہ تم کسی تحفے میں پیچھے نہ آؤ؛ ہمارے رب یسوع مسیح کے آنے کا انتظار: {آ رہا ہے: انگریز مکاشف}\n8۔ جو تمہیں آخر تک ثابت کرے گا، {تاکہ تم ہمارے رب یسوع مسیح کے دن بے قصور رہو۔\n9۔ خدا {ہے} وفادار، جس کے ذریعے آپ کو اس کے بیٹے یسوع مسیح ہمارے رب کی رفاقت کے لیے بلایا گیا۔\n10۔ اب میں آپ سب سے التجا کرتا ہوں، بھائیو، ہمارے رب یسوع مسیح کے نام پر، کہ آپ سب ایک ہی بات کہیں، اور {تاکہ} آپ کے درمیان کوئی اختلاف نہ ہو؛ لیکن {کہ} تم دونوں ایک ہی ذہن اور ایک ہی فیصلے میں مکمل طور پر جڑے رہو۔ {تقسیمات: Gr. Schisms}\n11۔ کیونکہ مجھے یہ اعلان کیا گیا ہے کہ تم سب کے بارے میں، میرے بھائیو، کلوئی کے گھرانے سے جو لوگ ہیں، کہ تم دونوں میں اختلافات ہیں۔\n12۔ اب میں یہ کہتا ہوں، کہ تم میں سے ہر ایک کہتا ہے، میں پولوس کا ہوں؛ اور اپولوس کی اول؛ اور میں سیفاس سے؛ اور میں مسیح کا ہوں۔\n13. کیا مسیح تقسیم شدہ ہے؟ کیا پال کو آپ کے لیے مصلوب کیا گیا؟ یا آپ کو پولس کے نام پر بپتسمہ دیا گیا؟\n14۔ میں خدا کا شکر ادا کرتا ہوں کہ میں نے تم میں سے کسی کو بپتسمہ نہیں دیا، سوائے کرسپس اور گائوس کے؛\n15۔ کہیں کوئی یہ نہ کہے کہ میں نے اپنے نام پر بپتسمہ لیا ہے۔\n16۔ اور میں نے اسٹیفاناس کے گھرانے کو بھی بپتسمہ دیا: ویسے بھی، مجھے نہیں معلوم کہ میں نے کسی اور کو بپتسمہ دیا یا نہیں۔\n17۔ کیونکہ مسیح نے مجھے بپتسمہ دینے کے لیے نہیں بلکہ انجیل کی تبلیغ کے لیے بھیجا: الفاظ کی حکمت سے نہیں، ورنہ مسیح کا صلیب بے اثر ہو جائے گا۔ {الفاظ: یا، تقریر}\n18۔ کیونکہ صلیب کی تبلیغ ان لوگوں کے لیے ہے جو حماقت کو ہلاک کرتے ہیں؛ لیکن ہمارے لیے جو نجات پائے گئے ہیں، یہ خدا کی طاقت ہے۔\n19۔ کیونکہ یہ لکھا ہے، میں دانا کی حکمت کو تباہ کر دوں گا، اور محتاط لوگوں کی سمجھ کو بے اثر کر دوں گا۔\n20۔ عقلمند کہاں ہے؟ کاتب کہاں ہے؟ اس دنیا کا متنازعہ کہاں ہے؟ کیا خدا نے اس دنیا کی حکمت کو بے وقوف نہیں بنایا؟\n21. کیونکہ اس کے بعد خدا کی حکمت میں دنیا نے حکمت سے خدا کو نہیں جانا، بلکہ خدا کو تبلیغ کی حماقت سے خوش کیا کہ وہ ایمان والوں کو نجات دے۔\n22۔ کیونکہ یہودیوں کو ایک نشانی چاہیے، اور یونانی حکمت کی تلاش میں ہیں:\n23. لیکن ہم مسیح کو مصلوب کیا گیا تبلیغ کرتے ہیں، یہودیوں کے لیے رکاوٹ ہے، اور یونانیوں کی حماقت کے لیے؛\n24۔ بلکہ ان لوگوں کے لیے جنہیں یہودی اور یونانی دونوں کہلائے گئے ہیں، مسیح خدا کی طاقت اور خدا کی حکمت ہے۔\n25۔ کیونکہ خدا کی حماقت انسانوں سے زیادہ دانا ہے؛ اور خدا کی کمزوری انسانوں سے زیادہ طاقتور ہے۔\n26. کیونکہ تم دیکھتے ہو کہ تمہاری پکار کیسے دیکھی جاتی ہے، بھائیو، کہ جسم کے بعد بہت کم دانا لوگ، بہت سے طاقتور نہیں، بہت کم شریف، {بلائے جاتے ہیں}:\n27۔ لیکن خدا نے دنیا کی بے وقوفانہ چیزوں کو حکمت والوں کو الجھانے کے لیے چنا ہے؛ اور خدا نے دنیا کی کمزور چیزوں کو چنا ہے تاکہ طاقتور چیزوں کو الجھا دے؛\n28۔ اور دنیا کی نیچی چیزیں، اور وہ چیزیں جو حقیر ہیں، خدا نے منتخب کی ہیں، {ہاں}، اور جو نہیں، وہ چیزیں ختم کر دیں جو ہیں:\n29۔ کہ کوئی جسم اس کی موجودگی میں فخر نہ کرے۔\n30۔ لیکن تم مسیح یسوع میں اس سے ہو، جو خدا کی طرف سے ہمارے لیے حکمت، راستبازی، تقدیس اور نجات کے لیے بنایا گیا ہے:\n31۔ کہ، جیسا کہ لکھا ہے، جو جلال پاتا ہے، وہ خداوند میں جلال دے۔","1۔ اور میں، بھائیو، جب میں آپ کے پاس آیا، تو نہ تو بڑی تقریر یا حکمت کے ساتھ آیا، اور آپ کو خدا کی گواہی دینے کا اعلان نہیں کیا۔\n2۔ کیونکہ میں نے فیصلہ کیا ہے کہ تم میں سے کچھ نہیں جانوں گا، سوائے یسوع مسیح کے، اور اسے صلیب پر چڑھایا گیا۔\n3۔ اور میں تمہارے ساتھ کمزوری، خوف میں، اور بہت لرزتے ہوئے تھا۔\n4۔ اور میری تقریر اور تبلیغ انسان کی حکمت کے دلکش الفاظ سے نہیں بلکہ روح اور طاقت کے مظاہرے میں تھی: {دلکش: یا، قائل کرنے والا}\n5۔ کہ آپ کا ایمان انسانوں کی حکمت میں نہیں بلکہ خدا کی طاقت پر قائم ہونا چاہیے۔ {کھڑا ہو: Gr. be}\n6۔ اگرچہ ہم ان میں حکمت کی بات کرتے ہیں جو کامل ہیں: لیکن نہ اس دنیا کی حکمت اور نہ ہی اس دنیا کے شہزادوں کی، جو ناکام رہے:\n7۔ لیکن ہم خدا کی حکمت کو ایک راز میں بیان کرتے ہیں، {حتیٰ کہ} پوشیدہ {حکمت}، جو خدا نے دنیا کے سامنے ہمارے جلال کے لیے مقرر کی ہے:\n8۔ جو اس دنیا کے کسی شہزادے کو معلوم نہیں تھا: کیونکہ اگر وہ جانتے تو جلال کے رب کو مصلوب نہ کرتے۔\n9۔ لیکن جیسا کہ لکھا ہے، آنکھ نے نہ دیکھا، نہ کان سنا، نہ انسان کے دل میں وہ چیزیں داخل ہوئی ہیں جو خدا نے ان لوگوں کے لیے تیار کی ہیں جو اس سے محبت کرتے ہیں۔\n10۔ لیکن خدا نے اپنی روح سے ہمیں ان سب کو ظاہر کیا ہے: کیونکہ روح ہر چیز کو تلاش کرتی ہے، ہاں، خدا کی گہرائی میں۔\n11۔ کیونکہ کون انسان انسان کی باتوں کو جانتا ہے، سوائے اس انسان کی روح کے جو اس میں ہے؟ اسی طرح خدا کی چیزیں انسان کو نہیں جانتیں، سوائے خدا کی روح کے۔\n12۔ اب ہم نے دنیا کی روح نہیں بلکہ خدا کی روح قبول کی ہے؛ تاکہ ہم وہ چیزیں جان سکیں جو ہمیں خدا کی طرف سے مفت دی گئی ہیں۔\n13۔ کون سی باتیں ہم بھی بولتے ہیں، نہ کہ ان الفاظ میں جو انسان کی حکمت سکھاتی ہے، بلکہ جو روح القدس سکھاتا ہے؛ روحانی باتوں کا موازنہ روحانی چیزوں سے کرنا۔\n14۔ لیکن قدرتی انسان خدا کی روح کی چیزیں قبول نہیں کرتا: کیونکہ وہ اس کے لیے حماقت ہیں: نہ ہی وہ انہیں جان سکتا ہے، کیونکہ وہ روحانی طور پر سمجھی جاتی ہیں۔\n15۔ لیکن جو روحانی ہے وہ سب چیزوں کا فیصلہ کرتا ہے، پھر بھی خود کسی انسان کا فیصلہ نہیں ہوتا۔ {juth: or, discerneth} {judged: or, discerned} {judged: or, discerned}\n16۔ کیونکہ کون ہے جو خداوند کے ذہن کو جانتا ہے، تاکہ وہ اسے ہدایت دے؟ لیکن ہمارے پاس مسیح کا ذہن ہے۔ {may: Gr. shall}","1۔ اور میں، بھائیو، تم سے روحانی کے طور پر بات نہیں کر سکا، بلکہ جسمانی طور پر، {حتیٰ کہ} جیسے مسیح میں بچوں کے لیے۔\n2۔ میں نے تمہیں دودھ سے کھلایا ہے، گوشت سے نہیں: کیونکہ اب تک تم برداشت نہیں کر سکتے تھے، اور اب بھی نہیں ہو۔\n3۔ کیونکہ تم ابھی بھی جسمانی ہو: کیونکہ جب تم میں حسد، جھگڑا اور تقسیم ہے، تو کیا تم جسمانی نہیں اور مردوں کی طرح نہیں چلتے؟ {تقسیم: یا، دھڑے} {مردوں کے طور پر: Gr. مطابق انسان؟}\n4۔ کیونکہ جب کوئی کہتا ہے، میں پولس کا ہوں؛ اور ایک اور، میں اپولوس کا ہوں؛ کیا تم جسمانی نہیں ہو؟\n5۔ تو پھر پولس کون ہے، اور اپولس کون ہے، مگر وہ خدمت گزار جن پر تم ایمان لاتے ہو، جیسے خداوند نے ہر انسان کو دیا؟\n6. میں نے بوئے، اپولوس نے پانی دیا؛ لیکن خدا نے اضافہ دیا۔\n7۔ تو نہ ہی وہ جو کچھ بوتا ہے، نہ ہی وہ جو پانی دیتا ہے؛ لیکن خدا جو اضافہ دیتا ہے۔\n8۔ اب جو بودے بوتا ہے اور جو پانی دیتا ہے وہ ایک ہیں: اور ہر انسان کو اپنی محنت کے مطابق اجر ملے گا۔\n9۔ کیونکہ ہم خدا کے ساتھ مل کر مزدور ہیں: آپ خدا کی پرورش ہیں، اور آپ خدا کی تعمیر ہیں۔ {ہزارنڈری: یا، ٹیلیج}\n10. خدا کے فضل کے مطابق جو مجھے دیا گیا ہے، ایک دانا ماسٹر بلڈر کے طور پر، میں نے بنیاد رکھی ہے، اور دوسرا اس پر تعمیر کرتا ہے۔ لیکن ہر انسان دھیان دے کہ وہ اس پر کیسے تعمیر کرتا ہے۔\n11۔ کیونکہ کوئی اور بنیاد نہیں رکھ سکتا سوائے اس کے جو رکھی گئی ہے، یعنی یسوع مسیح۔\n12۔ اب اگر کوئی اس بنیاد پر سونا، چاندی، قیمتی پتھر، لکڑی، گھاس، داڑھی تعمیر کرے گا؛\n13۔ ہر انسان کا کام ظاہر ہوگا: کیونکہ دن اسے ظاہر کرے گا، کیونکہ یہ آگ سے ظاہر ہوگا؛ اور آگ ہر انسان کے کام کو آزمائے گی، چاہے وہ کس قسم کا ہو۔ {یہ ہوگا: گری۔ یہ ہے}\n14۔ اگر کسی شخص کا کام اس پر قائم رہتا ہے جس پر اس نے تعمیر کیا ہے، تو اسے انعام ملے گا۔\n15۔ اگر کسی کا کام جل جائے تو اسے نقصان ہوگا، لیکن وہ خود بچایا جائے گا؛ پھر بھی آگ کے ذریعے۔\n16۔ کیا تم نہیں جانتے کہ تم خدا کے مندر ہو، اور خدا کی روح تم میں رہتی ہے؟\n17۔ اگر کوئی شخص خدا کے مندر کو ناپاک کرے گا، تو خدا اسے تباہ کرے گا؛ کیونکہ خدا کا مندر مقدس ہے، جو {مندر} تم ہو۔ {ناپاک: یا، تباہ کرو}\n18۔ کوئی انسان خود کو دھوکہ نہ دے۔ اگر تم میں سے کوئی آدمی اس دنیا میں دانا لگتا ہے، تو وہ بیوقوف بن جائے تاکہ وہ دانا بن سکے۔\n19۔ کیونکہ اس دنیا کی حکمت خدا کے ساتھ حماقت ہے۔ کیونکہ یہ لکھا ہے، وہ عقلمندوں کو ان کی چالاکی میں لیتا ہے۔\n20. اور پھر، خداوند جانتا ہے کہ دانا لوگوں کے خیالات بیکار ہیں۔\n21. اس لیے کوئی انسان انسانوں پر فخر نہ کرے۔ کیونکہ سب چیزیں تمہاری ہیں؛\n22۔ چاہے پولس، یا اپولوس، یا کیفاس، یا دنیا، یا زندگی، یا موت، یا موجودہ چیزیں، یا آنے والی چیزیں؛ سب تمہارے ہیں؛\n23. اور تم مسیح کے ہو؛ اور مسیح خدا کا ہے۔","1۔ ایک آدمی ہمارے بارے میں ایسا حساب دے، جیسے مسیح کے خادموں اور خدا کے اسرار کے محافظوں کے بارے میں۔\n2. مزید برآں، اسٹیورڈز میں یہ ضروری ہے کہ کوئی شخص وفادار پایا جائے۔\n3۔ لیکن میرے لیے یہ بہت چھوٹی بات ہے کہ مجھے آپ یا انسان کے فیصلے کا فیصلہ کیا جائے: ہاں، میں اپنے آپ کا فیصلہ نہیں کرتا۔ {ججمنٹ: گریڈ ڈے}\n4۔ کیونکہ میں خود سے کچھ نہیں جانتا؛ پھر بھی میں یہاں راستباز نہیں ہوں: لیکن جو میرا فیصلہ کرتا ہے وہ خداوند ہے۔ {جانیں: یا، میں کسی غلطی کا شعور نہیں رکھتا}\n5۔ اس لیے وقت سے پہلے کچھ نہ فیصلہ کرو، جب تک خداوند نہ آئے، جو دونوں تاریکی کی پوشیدہ باتیں ظاہر کرے اور دلوں کی نصیحتیں ظاہر کرے: اور پھر ہر انسان کو خدا کی تعریف ملے گی۔\n6۔ اور یہ چیزیں، بھائیو، میں نے ایک شکل میں اپنے پاس منتقل کی ہے اور آپ کی خاطر، اپولوس کو؛ تاکہ تم ہم میں سیکھو کہ انسانوں کے بارے میں اس سے زیادہ نہ سوچو جو لکھا ہے، تاکہ تم میں سے کوئی ایک دوسرے کے خلاف فخر نہ کرے۔\n7۔ کیونکہ کون تمہیں دوسروں سے مختلف بناتا ہے؟ اور تمہارے پاس کیا ہے جو تمہیں نہیں ملا؟ اب اگر تم نے اسے قبول کیا ہے، تو تم کیوں فخر کرتے ہو، جیسے تم نے اسے نہیں پایا ہو؟ {بناتا ہے...: Gr. distincteits the}\n8۔ اب تم مکمل ہو، اب تم امیر ہو، تم نے ہمارے بغیر بادشاہوں کی طرح حکومت کی: اور میں خدا سے چاہتا ہوں کہ تم بادشاہ ہو، تاکہ ہم بھی تمہارے ساتھ حکومت کریں۔\n9۔ کیونکہ میں سمجھتا ہوں کہ خدا نے ہمیں رسولوں کو آخری میں بھیجا ہے، جیسا کہ اسے موت کے لیے مقرر کیا گیا تھا: کیونکہ ہم دنیا، فرشتوں اور انسانوں کے لیے ایک تماشا بن گئے ہیں۔ {ہم...: یا، ہم آخری رسول، جیسا کہ} {تماشہ: گریڈ تھیٹر}\n10۔ ہم مسیح کی خاطر بیوقوف ہیں، لیکن تم مسیح میں دانا ہو؛ ہم کمزور ہیں، لیکن تم مضبوط ہو؛ تم معزز ہو، لیکن ہم حقیر ہیں۔\n11۔ آج تک ہم بھوکے، پیاسے، ننگے ہیں، مار کھاتے ہیں، اور کوئی خاص رہائش گاہ نہیں ہے؛\n12۔ اور محنت، اپنے ہاتھوں سے کام کرتے ہوئے: نفرت زدہ ہونے پر ہم برکت دیتے ہیں؛ ظلم و ستم کا شکار ہو کر ہم اسے برداشت کرتے ہیں:\n13۔ بدنام ہونے کی وجہ سے ہم التجا کرتے ہیں: ہم دنیا کی گندگی بن چکے ہیں، {اور آج تک تمام چیزوں کا خاتمہ ہیں}۔\n14. میں یہ باتیں آپ کو شرمندہ کرنے کے لیے نہیں لکھتا، بلکہ اپنے پیارے بیٹوں کی حیثیت سے آپ کو خبردار کرتا ہوں۔\n15۔ اگرچہ آپ کے پاس مسیح میں دس ہزار استاد ہیں، پھر بھی آپ کے زیادہ باپ نہیں ہیں: کیونکہ میں نے مسیح یسوع میں آپ کو انجیل کے ذریعے پیدا کیا ہے۔\n16۔ اسی لیے میں آپ سے التجا کرتا ہوں، میرے پیروکار بنو۔\n17۔ اسی مقصد کے لیے میں نے تمہارے پاس تیموتھیئس کو بھیجا ہے، جو میرا محبوب بیٹا ہے، اور خداوند میں وفادار ہے، جو تمہیں میرے راستوں کی یاد دلائے گا جو مسیح میں ہیں، جیسا کہ میں ہر کلیسیا میں ہر جگہ تعلیم دیتا ہوں۔\n18۔ اب کچھ لوگ پھولی ہوئی ہیں، جیسے میں تمہارے پاس نہیں آنا چاہتا۔\n19۔ لیکن میں جلد ہی آپ کے پاس آؤں گا، اگر خداوند چاہے، اور جانتا ہے، ان لوگوں کی بات نہیں جو مبالغہ آمیز ہیں، بلکہ طاقت کو۔\n20۔ کیونکہ خدا کی بادشاہی الفاظ میں نہیں، بلکہ طاقت میں ہے۔\n21. تم کیا کرو گے؟ کیا میں تمہارے پاس لاٹھی لے کر آؤں، یا محبت میں، اور نرمی کے جذبے کے ساتھ؟","1۔ عام طور پر یہ بتایا جاتا ہے کہ آپ میں ہوتا ہے، اور ایسی جو غیر یہودیوں میں نام بھی نہیں رکھتی، اس لیے کسی کو اپنے والد کی بیوی ملنی چاہیے۔\n2۔ اور تم پھولے ہوئے ہو، اور صرف غمگین نہیں ہوئے کہ جس نے یہ کام کیا ہے اسے تم میں سے چھین لیا جائے۔\n3۔ کیونکہ میں واقعی، جسمانی طور پر غیر حاضر مگر روح میں موجود، پہلے ہی فیصلہ کر چکا ہوں، جیسے میں موجود ہوں، {اس کے بارے میں} جس نے یہ عمل کیا، {فیصلہ کیا: یا، طے شدہ}\n4۔ ہمارے رب یسوع مسیح کے نام پر، جب تم سب اکٹھے ہو اور میری روح ہمارے رب یسوع مسیح کی طاقت سے،\n5. ایسے شخص کو شیطان کے حوالے کرنا تاکہ جسم کی تباہی ہو، تاکہ روح خداوند یسوع کے دن نجات پائے۔\n6. آپ کی شان اچھی نہیں ہے۔ کیا تم نہیں جانتے کہ تھوڑا سا خمیر پورے گانٹھ کو خمیر کر دیتا ہے؟\n7۔ اس لیے پرانا خمیر صاف کر دو، تاکہ تم نیا گٹھلی بن سکو، جیسا کہ تم خمیر سے پاک ہو۔ کیونکہ یہاں تک کہ مسیح بھی ہمارا فسح ہمارے لیے قربان کیا جاتا ہے: {قربانی دی جاتی ہے؛ یا، مارا جاتا ہے}\n8۔ لہٰذا ہم دعوت کو پرانے خمیر سے نہیں، نہ بد نیتی اور بدی کے خمیر سے؛ بلکہ خلوص اور سچائی کی بغیر خمیر کی روٹی کے ساتھ۔ {دی فیسٹ: یا، ہولی ڈے}\n9۔ میں نے تمہیں ایک خط میں لکھا تھا کہ میں بدکاروں کے ساتھ صحبت نہ کروں:\n10۔ لیکن اس دنیا کے کے ساتھ بالکل نہیں، نہ لالچی کرنے والوں، نہ بھتہ خوروں، نہ بت پرستوں کے ساتھ؛ کیونکہ پھر تمہیں دنیا سے باہر جانا ہوگا۔\n11۔ لیکن اب میں نے آپ کو خط لکھا ہے کہ اگر کوئی بھائی کہلاتا ہے تو وہ، لالچی، بت پرست، دھوکہ باز، شرابی یا بھتہ خور ہو تو آپ کا ساتھ نہ ملے؛ ایسے کسی کے ساتھ جو نہ کھانا ہے۔\n12. کیونکہ مجھے ان لوگوں کا بھی فیصلہ کرنے کے لیے کیا کرنا چاہیے جو اس کے بغیر ہیں؟ کیا آپ ان لوگوں کا فیصلہ نہیں کرتے جو اندر ہیں؟\n13۔ لیکن جو خدا کے بغیر ہیں وہ فیصلہ کرتے ہیں۔ لہٰذا اس بدکار شخص کو اپنے درمیان سے دور کر دو۔","1۔ کیا آپ میں سے کسی کو جو کسی دوسرے کے خلاف معاملہ رکھتا ہے، ناانصافیوں کے سامنے قانون کے سامنے جانے کی ہمت رکھتا ہے، نہ کہ مقدسین کے سامنے؟\n2۔ کیا تم نہیں جانتے کہ مقدسین دنیا کا فیصلہ کریں گے؟ اور اگر دنیا کا فیصلہ تم کرے، تو کیا تم چھوٹے چھوٹے معاملات کا فیصلہ کرنے کے لائق نہیں ہو؟\n3۔ کیا تم نہیں جانتے کہ ہم فرشتوں کا فیصلہ کریں گے؟ اور کتنی چیزیں اس زندگی سے متعلق ہیں؟\n4۔ اگر آپ کے پاس اس زندگی سے متعلق معاملات پر فیصلے ہیں، تو انہیں کلیسیا میں سب سے کم معزز لوگوں کے لیے مقرر کریں۔\n5. میں تمہاری شرمندگی کی بات کرتا ہوں۔ کیا ایسا ہے کہ تم میں سے کوئی دانا نہیں ہے؟ نہیں، کوئی ایسا نہیں جو اپنے بھائیوں کے درمیان فیصلہ کر سکے؟\n6۔ لیکن بھائی بھائی کے ساتھ قانون کی طرف جاتا ہے، اور وہ بھی کافروں کے سامنے۔\n7۔ اب تم دونوں میں مکمل غلطی ہے، کیونکہ تم ایک دوسرے کے ساتھ قانون کے پاس جاتے ہو۔ تم غلط کیوں نہیں سمجھتے؟ تم خود کو دھوکہ کھانے کی اجازت کیوں نہیں دیتے؟\n8۔ نہیں، تم غلط کرتے ہو، دھوکہ دیتے ہو، اور اپنے بھائیوں کو دھوکہ دیتے ہو۔\n9۔ کیا تم نہیں جانتے کہ بدکار خدا کی بادشاہی کا وارث نہیں بنیں گے؟ دھوکہ نہ کھاؤ: نہ، نہ بت پرست، نہ، نہ نسوانی، نہ انسانوں کے ساتھ اپنے ساتھ ظلم کرنے والے،\n10۔ نہ چور، نہ لالچی، نہ شرابی، نہ گالی دینے والے، نہ بھتہ خور، خدا کی بادشاہی کے وارث ہوں گے۔\n11۔ اور تم میں سے کچھ ایسے ہی تھے: لیکن تم دھوئے ہوئے ہو، لیکن تم پاک ہو، اور تم خداوند یسوع کے نام پر اور ہمارے خدا کی روح کے ذریعے راستباز ہو۔\n12۔ میرے لیے سب کچھ جائز ہے، لیکن سب کچھ مناسب نہیں: سب چیزیں میرے لیے جائز ہیں، لیکن میں کسی کے زیر اثر نہیں آؤں گا۔ {مصلحت: یا، منافع بخش}\n13۔ پیٹ کے لیے گوشت، اور پیٹ گوشت کے لیے: لیکن خدا اسے اور ان دونوں کو تباہ کر دے گا۔ اب جسم کے لیے نہیں، بلکہ خداوند کے لیے ہے؛ اور خدا جسم کے لیے۔ {گوشت: صرف گوشت نہیں، بلکہ کسی بھی قسم کا کھانا}\n14۔ اور خدا نے خداوند کو زندہ کیا ہے، اور اپنی طاقت سے ہمیں بھی زندہ کرے گا۔\n15۔ کیا تم نہیں جانتے کہ تمہارے جسم مسیح کے رکن ہیں؟ کیا میں مسیح کے ارکان کو لے کر انہیں ایک بدکار کے رکن بنا دوں؟ خدا نہ کرے۔\n16۔ کیا؟ کیا تم نہیں جانتے کہ جو ایک بدکار عورت سے جڑا ہوا ہے وہ ایک جسم ہے؟ دو کے لیے، وہ کہتا ہے، ایک جسم ہوگا۔\n17. لیکن جو خداوند سے جڑا ہے وہ ایک روح ہے۔\n18۔ سے بھاگو۔ ہر گناہ جو انسان کرتا ہے وہ جسم کے بغیر ہوتا ہے؛ لیکن جو کرتا ہے وہ اپنے جسم کے خلاف گناہ کرتا ہے۔\n19۔ کیا؟ کیا تم نہیں جانتے کہ تمہارا جسم روح القدس کا مندر ہے {جو تمہارے اندر ہے}، جو تمہارے پاس خدا کی طرف سے ہے، اور تم اپنے نہیں ہو؟\n20۔ کیونکہ تم قیمت کے ساتھ خریدے گئے ہو: اس لیے اپنے جسم اور اپنی روح میں خدا کی جلال کرو، جو خدا کی ہے۔","1۔ اب ان باتوں کے بارے میں جن کے بارے میں تم نے مجھے لکھا: {یہ اچھا ہے} کہ مرد عورت کو ہاتھ نہ لگائے۔\n2. تاہم، سے بچنے کے لیے، ہر مرد کو اپنی بیوی ہو، اور ہر عورت کو اپنا شوہر ملے۔\n3۔ شوہر بیوی کو مناسب مہربانی دے: اور اسی طرح بیوی بھی شوہر کو۔\n4۔ بیوی کے پاس اپنے جسم کی طاقت نہیں بلکہ شوہر کے پاس ہے؛ اور اسی طرح شوہر کے پاس اپنے جسم کی طاقت نہیں بلکہ بیوی کی طاقت ہے۔\n5. ایک دوسرے کو دھوکہ نہ دیں، سوائے اس کے کہ کچھ وقت کے لیے رضامندی سے خود کو روزہ اور دعا کے لیے وقف کر سکیں؛ اور دوبارہ اکٹھے ہو جائیں، کہ شیطان تمہیں تمہاری بے اختیاری کے لیے نہ لبھائے۔\n6۔ لیکن میں یہ بات اجازت سے کہہ رہا ہوں، {اور} حکم کے تحت نہیں۔\n7۔ کیونکہ میں چاہتا ہوں کہ تمام انسان میرے برابر ہوں۔ لیکن ہر انسان کو خدا کی طرف سے اس کا مناسب تحفہ ملتا ہے، ایک کے بعد ایک طرح، اور اس کے بعد دوسرا۔\n8۔ اس لیے میں غیر شادی شدہ اور بیواؤں سے کہتا ہوں، ان کے لیے اچھا ہے اگر وہ میری طرح رہیں۔\n9۔ لیکن اگر وہ قابو نہیں پا سکتے تو انہیں شادی کرنے دو: کیونکہ شادی کرنا جلنے سے بہتر ہے۔\n10۔ اور میں شادی شدہ کو حکم دیتا ہوں، {لیکن} میں نہیں بلکہ خداوند کو، بیوی کو {اپنے} شوہر سے جدا نہ کرے:\n11۔ اور اگر وہ چلی جائے تو اسے غیر شادی شدہ رہنے دیں، یا اپنے شوہر سے صلح کر لیں: اور شوہر اپنی بیوی کو چھوڑ نہ دے۔\n12. لیکن باقی لوگوں سے میں بات کرتا ہوں، نہ کہ خداوند سے: اگر کسی بھائی کی بیوی ہے جو ایمان نہیں رکھتی اور وہ اس کے ساتھ رہنے کو تیار ہے، تو اسے دور نہ کرے۔\n13۔ اور وہ عورت جس کا شوہر ایمان نہ لاتا ہو، اور اگر وہ اس کے ساتھ رہنا چاہے تو وہ اسے نہ چھوڑے۔\n14۔ کیونکہ کافر شوہر بیوی کی طرف سے پاک ہوتا ہے، اور کافر بیوی شوہر کی طرف سے پاک ہوتی ہے: ورنہ تمہارے بچے ناپاک ہوتے؛ لیکن اب کیا وہ مقدس ہیں۔\n15. لیکن اگر بے ایمان جانے والا چلا جائے تو اسے جانے دو۔ ایسے معاملات میں بھائی یا بہن غلام نہیں ہوتا: لیکن خدا نے ہمیں امن کی طرف بلایا ہے۔ {امن کے لیے: Gr. in peace}\n16. کیا تم جانتی ہو، اے بیوی، کہ کیا تم اپنے شوہر کو بچاؤ گی؟ یا تم کیسے جانتے ہو، اے انسان، کہ کیا تم اپنی بیوی کو بچاؤ گے؟ {کیسے: Gr. کیا}\n17۔ لیکن جیسے خدا نے ہر انسان کو تقسیم کیا ہے، جیسا کہ خداوند نے سب کو بلایا ہے، ویسے ہی اسے چلنے دے۔ اور اسی لیے میں تمام کلیساؤں میں پادری ہوں۔\n18. کیا کسی مرد کو ختنہ کہا جاتا ہے؟ اسے ختنہ نہ ہونے دو۔ کیا کسی کو ختنہ نہ کرنے میں کہا جاتا ہے؟ اسے ختنہ نہ ہونے دو۔\n19۔ ختنہ کچھ نہیں، اور غیر ختنہ کچھ نہیں، سوائے خدا کے احکامات کی پاسداری۔\n20۔ ہر آدمی اسی پکار میں رہے جس میں اسے بلایا گیا تھا۔\n21. کیا تمہیں خادم کہا جاتا ہے؟ اس کی پرواہ نہ کرو: لیکن اگر تم آزاد ہو سکتے ہو تو اسے استعمال کرو۔\n22۔ کیونکہ جو خداوند میں بلایا گیا ہے، {خادم ہے}، وہ خداوند کا آزاد آدمی ہے؛ اسی طرح جو بلایا گیا ہے، {آزاد} ہے، وہ مسیح کا خادم ہے۔ {فری مین: گری۔ آزاد کیا گیا}\n23. تم قیمت پر خریدے گئے ہو؛ انسانوں کے خادم نہ بنو۔\n24۔ بھائیو، ہر وہ شخص جس میں اسے بلایا گیا ہے، خدا کے ساتھ رہے۔\n25۔ اب کنواریوں کے بارے میں میرے پاس خداوند کا کوئی حکم نہیں ہے، پھر بھی میں اپنا فیصلہ دیتا ہوں، جیسا کہ وہ شخص ہے جس نے خدا کی رحمت حاصل کی ہے تاکہ وفادار رہے۔\n26. لہٰذا میرا خیال ہے کہ یہ موجودہ مصیبت کے لیے اچھا ہے، {میں کہتا ہوں}، کہ {یہ} ایک آنے والے انسان کے لیے اچھا ہے۔ {پریشانی: یا، ضرورت}\n27۔ کیا تم بیوی سے بندھے ہو؟ آزاد ہونے کی کوشش نہ کرو۔ کیا تم بیوی سے آزاد ہو گئے ہو؟ بیوی نہ مانگو۔\n28۔ لیکن اگر تم شادی کرو تو تم نے گناہ نہیں کیا؛ اور اگر کنواری شادی کرے تو اس نے گناہ نہیں کیا۔ پھر بھی، ایسے لوگ جسمانی طور پر مشکلات کا سامنا کریں گے: لیکن میں تمہیں معاف کرتا ہوں۔\n29۔ لیکن یہ میں کہتا ہوں، بھائیو، وقت کم ہے: یہ باقی ہے کہ دونوں بیویاں ایسے ہوں جیسے ان کی کوئی نہ ہو؛\n30۔ اور جو روتے ہیں، جیسے وہ روتے ہی نہیں؛ اور جو خوش ہوتے ہیں، جیسے وہ خوش نہ ہوں؛ اور جو خریدتے ہیں، جیسے ان کے پاس کوئی مالک نہ ہو؛\n31. اور جو لوگ اس دنیا کو استعمال کرتے ہیں، اس لیے کہ وہ اس کا غلط استعمال نہیں کر رہے: کیونکہ اس دنیا کا فیشن ختم ہو جاتا ہے۔\n32۔ لیکن میں تمہیں بغیر احتیاط کے چاہوں گا۔ جو غیر شادی شدہ ہے وہ خدا کی چیزوں کی پرواہ کرتا ہے، جیسا کہ وہ خداوند کو خوش کرے: {جو تعلق رکھتی ہیں...: Gr. of the Lord}\n33۔ لیکن جو شادی شدہ ہے وہ دنیا کی چیزوں کا خیال رکھتا ہے، جیسا کہ وہ اپنی بیوی کو خوش کرے۔\n34۔ بیوی اور کنواری میں بھی فرق ہے۔ غیر شادی شدہ عورت خداوند کی چیزوں کا خیال رکھتی ہے، تاکہ وہ جسم اور روح دونوں میں پاک رہے؛ لیکن جو شادی شدہ ہے وہ دنیا کی چیزوں کا خیال رکھتی ہے، چاہے وہ اپنے شوہر کو خوش کرے۔\n35۔ اور یہ میں آپ کے اپنے فائدے کے لیے کہتا ہوں؛ نہ کہ میں تم پر جال ڈال دوں، بلکہ اس کے لیے جو خوبصورت ہے، اور تاکہ تم بغیر کسی رکاوٹ کے خداوند کی خدمت کرو۔\n36۔ لیکن اگر کوئی شخص سمجھے کہ وہ اپنی کنواری کے ساتھ بدتمیزی کرتا ہے، اگر وہ اپنی عمر کے پھولوں سے گزر گئی اور ضرورت ہو، تو وہ جو چاہے کرے، وہ گناہ نہیں کرتا: انہیں شادی کرنے دو۔\n37۔ پھر بھی جو اپنے دل میں مضبوطی سے قائم رہتا ہے، اس کی ضرورت نہیں، لیکن اپنی مرضی پر اختیار رکھتا ہے، اور اپنے دل میں یہ طے کرتا ہے کہ وہ اپنی کنواری کو برقرار رکھے گا، وہ اچھا کرتا ہے۔\n38۔ تو جو شادی میں {اسے} دیتا ہے، وہ اچھا کرتا ہے؛ لیکن جو شادی میں نہیں دیتا وہ بہتر کرتا ہے۔\n39۔ بیوی قانون کی پابند ہے جب تک اس کا شوہر زندہ ہے؛ لیکن اگر اس کا شوہر فوت ہو چکا ہو، تو وہ جس سے چاہے شادی کر سکتی ہے؛ صرف خداوند میں۔\n40۔ لیکن وہ زیادہ خوش ہے اگر وہ میرے فیصلے کے بعد قائم رہے: اور میں یہ بھی سوچتا ہوں کہ میرے پاس خدا کی روح ہے۔","1. اب جب کہ بتوں کو چھونے والی چیزیں پیش کی جاتی ہیں، ہم جانتے ہیں کہ ہم سب کے پاس علم ہے۔ علم پھولتا ہے، لیکن سخاوت کو تقویت دیتی ہے۔\n2۔ اور اگر کوئی شخص سمجھے کہ وہ کچھ جانتا ہے، تو وہ ابھی کچھ نہیں جانتا جیسا کہ اسے جاننا چاہیے۔\n3۔ لیکن اگر کوئی خدا سے محبت کرتا ہے تو اس کے بارے میں بھی یہی معلوم ہے۔\n4۔ اس لیے ان چیزوں کے کھانے کے بارے میں جو بتوں کو قربانی کے طور پر پیش کی جاتی ہیں، ہم جانتے ہیں کہ بت دنیا میں کچھ نہیں ہے، اور {کوئی اور خدا نہیں} سوائے ایک کے۔\n5. کیونکہ اگرچہ خدا کہلانے والے ہوں، چاہے آسمان میں ہوں یا زمین پر، (جیسے بہت سے خدا اور بہت سے خداوند ہیں،)\n6۔ لیکن ہمارے لیے {صرف ایک خدا ہے}، باپ، جس کی سب چیزیں {ہیں}، اور ہم اس میں ہیں؛ اور ایک خداوند یسوع مسیح، جس کے ذریعے سب کچھ ہے، اور ہم اس کے ذریعے ہیں۔ {in: or, for}\n7۔ تاہم ہر انسان میں یہ علم نہیں ہوتا: کیونکہ کچھ لوگ اس وقت تک بت کے بارے میں ضمیر رکھتے ہیں {اسے} کو ایک چیز کی طرح کھاتے ہیں جو بت کو پیش کی جاتی ہے؛ اور ان کا ضمیر کمزور ہو جاتا ہے۔\n8۔ لیکن گوشت ہمیں خدا کے سپرد نہیں کرتا: کیونکہ اگر ہم کھائیں تو ہم بہتر نہیں ہوتے؛ اور اگر ہم نہ کھائیں تو ہم بھی بدتر ہیں۔ {کیا ہم بہتر ہیں: یا، کیا ہم زیادہ ہیں} {کیا ہم بدتر ہیں: یا کم ہیں}\n9۔ لیکن خبردار رہو کہ کہیں یہ آزادی کسی بھی طرح کمزوروں کے لیے رکاوٹ نہ بن جائے۔ {آزادی: یا، طاقت}\n10۔ کیونکہ اگر کوئی شخص تمہیں بتوں کے مندر میں گوشت پر بیٹھا دیکھے جس کے پاس علم ہے، تو کمزور کا ضمیر وہ چیزیں کھانے کی ہمت نہیں کرے گا جو بتوں کو دی جاتی ہیں؟ {حوصلہ افزائی: Gr. edified}\n11۔ اور تیری علم کے ذریعے وہ کمزور بھائی فنا ہوگا جس کے لیے مسیح مرا؟\n12۔ لیکن جب تم بھائیوں کے خلاف ایسا گناہ کرتے ہو اور ان کے کمزور ضمیر کو ٹھیس پہنچاتے ہو، تو تم مسیح کے خلاف گناہ کرتے ہو۔\n13۔ لہٰذا، اگر گوشت میرے بھائی کو ناراض کرے، تو میں دنیا کے قیام کے دوران گوشت نہیں کھاؤں گا، ورنہ میں اپنے بھائی کو ناراض کر دوں گا۔","1. کیا میں رسول نہیں ہوں؟ کیا میں آزاد نہیں ہوں؟ کیا میں نے یسوع مسیح ہمارے رب کو نہیں دیکھا؟ کیا تم میرے کام خداوند میں نہیں ہو؟\n2۔ اگر میں دوسروں کے لیے رسول نہیں ہوں، تو یقینا میں تمہارے لیے ہوں: کیونکہ میری رسولی کی مہر تم خداوند میں ہو۔\n3. میرا جواب ان لوگوں کے لیے جو مجھے پرکھتے ہیں وہ یہ ہے،\n4. کیا ہمارے پاس کھانے پینے کی طاقت نہیں؟\n5. کیا ہمارے پاس یہ اختیار نہیں کہ ہم بہن، بیوی، دیگر رسولوں اور خداوند کے بھائیوں اور سیفاس کے بارے میں رہنمائی کریں؟ {بیوی: یا، عورت}\n6۔ یا صرف میں اور بارناباس، کیا ہمیں کام کرنے سے باز رہنے کی طاقت نہیں؟\n7. کون اپنی ہی ذمہ داری پر جنگ میں جاتا ہے؟ جو انگور کا باغ بوتا ہے اور اس کے پھل نہیں کھاتا؟ یا جو ریوڑ کو کھلاتا ہے اور ریوڑ کا دودھ نہیں کھاتا؟\n8۔ کیا میں یہ باتیں ایک مرد کے طور پر کہتا ہوں؟ یا قانون بھی یہی نہیں کہتا؟\n9۔ کیونکہ موسیٰ کے قانون میں لکھا ہے، تو اس بیل کے منہ کو منہ بند نہ کرو جو منہ سے نکلتا ہے۔ کیا خدا بیلوں کا خیال رکھتا ہے؟\n10۔ یا وہ کہتا ہے کہ یہ سب ہمارے لیے ہے؟ ہمارے فائدے کے لیے، بلا شبہ، {یہ} لکھا ہے: جو ہل چلاتا ہے وہ امید میں ہل چلائے؛ اور جو امید میں پھینکتا ہے وہ اس کی امید کا شریک ہو۔\n11۔ اگر ہم نے آپ کے لیے روحانی چیزیں بوئی ہیں، تو کیا یہ بڑی بات ہے اگر ہم آپ کی جسمانی چیزیں کاٹیں؟\n12۔ اگر دوسرے آپ پر اس طاقت کے شریک ہیں، تو کیا ہم نہیں؟ تاہم ہم نے یہ طاقت استعمال نہیں کی؛ لیکن سب کچھ برداشت کرو، ورنہ ہم مسیح کی خوشخبری میں رکاوٹ بنیں گے۔\n13۔ کیا تم نہیں جانتے کہ جو لوگ مقدس چیزوں کی خدمت کرتے ہیں وہ ہیکل کی چیزوں میں سے زندہ رہتے ہیں؟ اور جو قربان گاہ پر انتظار کرتے ہیں وہ قربان گاہ کے ساتھ شریک ہیں؟ {لائیو: یا، فیڈ}\n14۔ اسی طرح خداوند نے حکم دیا ہے کہ جو لوگ انجیل کی تبلیغ کرتے ہیں وہ انجیل کے مطابق زندہ رہیں۔\n15۔ لیکن میں نے ان میں سے کوئی بھی چیز استعمال نہیں کی: نہ ہی میں نے یہ سب لکھا کہ میرے ساتھ ایسا کیا جائے: کیونکہ میرے لیے مرنا بہتر تھا، بجائے اس کے کہ کوئی شخص میری شان کو منسوخ کر دے۔\n16۔ کیونکہ اگرچہ میں انجیل کی تبلیغ کرتا ہوں، میرے پاس فخر کرنے کے لیے کچھ نہیں: کیونکہ ضرورت مجھ پر عائد کی گئی ہے؛ ہاں، میرے لیے افسوس ہے اگر میں انجیل کی تبلیغ نہ کروں!\n17۔ کیونکہ اگر میں یہ کام رضاکارانہ طور پر کروں تو مجھے انعام ملے گا: لیکن اگر میری مرضی کے خلاف ہو تو مجھے انجیل کی استثنیٰ دی گئی ہے۔\n18. پھر میرا انعام کیا ہے؟ {یقینا} کہ جب میں انجیل کی تبلیغ کروں، تو میں مسیح کی خوشخبری بلا معاوضہ بنا سکوں، تاکہ میں انجیل میں اپنی طاقت کا غلط استعمال نہ کروں۔\n19۔ کیونکہ اگرچہ میں سب {انسان} سے آزاد ہوں، پھر بھی میں نے خود کو سب کا خادم بنا لیا ہے، تاکہ میں زیادہ فائدہ اٹھا سکوں۔\n20. اور میں یہودیوں کے لیے جو میں یہودی بن گیا، تاکہ یہودیوں کو حاصل کر سکوں؛ ان کے لیے جو قانون کے تحت ہیں، جیسے قانون کے تحت، تاکہ میں ان لوگوں کو حاصل کر سکوں جو قانون کے تحت ہیں؛\n21۔ ان لوگوں کے لیے جو قانون کے بغیر ہیں، جیسے کہ قانون کے بغیر، (خدا کے لیے قانون کے بغیر نہیں، بلکہ مسیح کے قانون کے تحت ہیں)، تاکہ میں ان لوگوں کو حاصل کر سکوں جو قانون سے محروم ہیں۔\n22۔ کمزوروں کے لیے میں کمزور بن گیا، تاکہ کمزوروں کو حاصل کر سکوں: میں سب لوگوں کے لیے سب کچھ بن گیا ہوں، تاکہ میں ہر طرح سے کچھ کو بچا سکوں۔\n23۔ اور یہ میں انجیل کی خاطر کرتا ہوں، تاکہ میں اس میں آپ کے ساتھ شریک ہو سکوں۔\n24۔ کیا تم نہیں جانتے کہ جو دوڑ میں دوڑتے ہیں وہ سب دوڑتے ہیں، سوائے ایک کے، انعام پاتے ہیں؟ تو دوڑو، تاکہ تم حاصل کر سکو۔\n25۔ اور ہر وہ شخص جو حکمرانی کی کوشش کرتا ہے، ہر چیز میں معتدل ہوتا ہے۔ اب وہ {یہ کرتے ہیں} تاکہ ایک کرپٹ ہونے والا تاج حاصل کر سکیں؛ لیکن ہم ایک ناقابل فساد ہیں۔\n26. لہٰذا میں دوڑتا ہوں، اتنا غیر یقینی نہیں؛ لہٰذا میں لڑتا ہوں، نہ کہ ہوا کو مارنے والے کے طور پر:\n27. لیکن میں اپنے جسم کے نیچے رکھتا ہوں، اور اسے تابع کرتا ہوں: کہیں کسی بھی طرح، جب میں نے دوسروں کو تبلیغ کی ہو، تو میں خود بھی بے دخل ہو جاؤں۔","1۔ مزید یہ کہ، بھائیو، میں نہیں چاہتا کہ آپ لاعلم ہوں کہ ہمارے تمام باپ و اجداد بادلوں کے نیچے تھے، اور سب سمندر سے گزر گئے؛\n2۔ اور سب کو موسیٰ کے لیے بادل اور سمندر میں بپتسمہ دیا گیا؛\n3۔ اور سب نے ایک ہی روحانی گوشت کھایا؛\n4۔ اور سب نے ایک ہی روحانی مشروب پیا: کیونکہ انہوں نے اس روحانی چٹان سے پانی لیا جو ان کے پیچھے تھا: اور وہ چٹان مسیح تھا۔ {فالو کیا...: یا، ان کے ساتھ چلا گیا}\n5۔ لیکن ان میں سے بہت سے لوگوں سے خدا خوش نہیں ہوا: کیونکہ وہ بیابان میں شکست کھا گئے۔\n6۔ اب یہ چیزیں ہماری مثالیں تھیں، اس نیت سے کہ ہمیں برے کاموں کی خواہش نہیں کرنی چاہیے، جیسا کہ وہ بھی ہوس کرتی تھیں۔ {ہمارے...: Gr. ہمارے اعداد و شمار}\n7۔ نہ ہی تم بت پرست ہو، جیسا کہ ان میں سے کچھ تھے؛ جیسا کہ لکھا ہے، لوگ بیٹھ کر کھاتے اور پیتے اور پھر کھیلنے کے لیے اٹھ کھڑے ہو جاتے۔\n8۔ ہم بھی نہ کریں، جیسا کہ کچھ نے کیا، اور ایک دن میں تین ہزار میں گر گئے۔\n9۔ نہ ہی ہم مسیح کو آزمائش میں ڈالیں، جیسا کہ ان میں سے کچھ نے بھی آزمائش کی اور سانپوں سے تباہ ہو گئے۔\n10۔ نہ تم سرگوشی کرتے، کیونکہ کچھ نے بھی سرگوشی کی، اور تباہ کن جہاز تباہ ہو گئے۔\n11۔ اب یہ سب چیزیں ان کے ساتھ نمونوں کے طور پر ہوئیں: اور یہ ہمارے نصیحت کے لیے لکھی گئی ہیں، جن پر دنیا کے خاتمے آتے ہیں۔ {ensamples: or, types}\n12۔ اسی لیے جو سمجھتا ہے کہ وہ کھڑا ہے، وہ ہوشیار ہو کہ کہیں وہ گر نہ جائے۔\n13۔ تمہیں کوئی آزمائش نہیں ملی سوائے اس کے جو انسان کے لیے عام ہے: لیکن خدا وفادار ہے، جو تمہیں تمہاری صلاحیت سے زیادہ آزمائش میں نہیں آنے دے گا؛ لیکن آزمائش کے ساتھ فرار کا راستہ بھی نکالو گے، تاکہ تم اسے برداشت کر سکو۔ {عام...: یا، معتدل}\n14. اسی لیے، میرے عزیز محبوبو، بت پرستی سے دور ہو جاؤ۔\n15۔ میں عقلمندوں کے بارے میں بات کرتا ہوں؛ میری بات کا فیصلہ کرو۔\n16۔ وہ برکت کا پیالہ جسے ہم برکت دیتے ہیں، کیا یہ مسیح کے خون کی کمیونین نہیں ہے؟ جو روٹی ہم توڑتے ہیں، کیا وہ مسیح کے جسم کی کمیونین نہیں ہے؟\n17. کیونکہ ہم {وجود} بہت سے ایک روٹی ہیں، {اور} ایک جسم ہیں: کیونکہ ہم سب اس ایک روٹی کے شریک ہیں۔\n18. دیکھو اسرائیل جسم کے بعد سے: کیا جو قربانی میں سے کھاتے ہیں وہ قربان گاہ کے شریک نہیں ہیں؟\n19۔ پھر میں کیا کہوں؟ کہ بت کوئی چیز ہے، یا جو بت کے لیے قربانی میں پیش کی جاتی ہے وہ کچھ ہے؟\n20۔ لیکن میں {کہتا ہوں} کہ جو چیزیں غیر یہودی قربان کرتے ہیں، وہ شیطانوں کے لیے قربان کرتے ہیں، خدا کے لیے نہیں: اور میں نہیں چاہتا کہ تم شیطانوں کے ساتھ رفاقت کرو۔\n21. تم خداوند کا پیالہ اور شیطانوں کا پیالہ نہیں پی سکتے: تم خداوند کے دسترخوان اور شیطانوں کی میز میں شریک نہیں ہو سکتے۔\n22۔ کیا ہم خداوند کو حسد پر اکساتے ہیں؟ کیا ہم اس سے زیادہ طاقتور ہیں؟\n23. میرے لیے سب کچھ جائز ہے، لیکن سب کچھ مناسب نہیں: سب چیزیں میرے لیے جائز ہیں، لیکن سب چیزیں ابھرتی نہیں۔ {مفید: یا، فائدہ مند}\n24۔ کوئی شخص اپنی دولت نہ مانگے، بلکہ ہر انسان کی دولت تلاش کرے۔\n25۔ جو کچھ بھی بدحال میں بیچا جاتا ہے، {جو} کھاتا ہے، ضمیر کے لیے کوئی سوال نہ کرے:\n26۔ کیونکہ زمین {ہے} خداوند کی، اور اس کی بھرپوری۔\n27۔ اگر کوئی بھی جو ایمان نہیں لاتا ہے تمہیں دعوت کے لیے بلائے، اور تم جانے کے لیے تیار ہو؛ جو کچھ بھی آپ کے سامنے ہے، کھائیں، ضمیر کی خاطر کوئی سوال نہ کریں۔\n28۔ لیکن اگر کوئی تم سے کہے کہ یہ بت پرستوں کے لیے قربانی کے طور پر پیش کی گئی ہے، تو اس کے لیے نہ کھاؤ جس نے یہ دکھایا ہے، اور ضمیر کے لیے: کیونکہ زمین خدا کی ہے، اور اس کی بھرپوری:\n29۔ ضمیر، میں کہتا ہوں، تمہارا اپنا نہیں، بلکہ دوسرے کا: کیونکہ میری آزادی دوسرے {انسان} کے ضمیر سے کیوں پکی جاتی ہے؟\n30۔ کیونکہ اگر میں فضل سے شریک ہوں، تو مجھے اس چیز کے لیے کیوں برا کہا جاتا ہے جس کے لیے میں شکر ادا کرتا ہوں؟ {گریس: یا، تھینکس گیونگ}\n31۔ اس لیے چاہے آپ کھائیں، یا پیئیں، یا جو کچھ بھی کریں، سب خدا کی جلال کے لیے کریں۔\n32. نہ یہودیوں کو، نہ غیر یہودیوں کو، نہ خدا کی کلیسیا کو برا نہ مانو: {غیر یہودی: یونانی یونانی}\n33. جیسا کہ میں سب {انسان} کو ہر {چیز} میں خوش کرتا ہوں، اپنے ذاتی فائدے کے لیے نہیں، بلکہ بہت سے لوگوں کے {فائدے} کے لیے، تاکہ وہ نجات پا سکیں۔","1. میرے پیروکار بنو، جیسے میں بھی مسیح کا {ہوں}۔\n2۔ اب میں آپ کی تعریف کرتا ہوں، بھائیو، کہ آپ مجھے ہر چیز میں یاد رکھتے ہیں اور احکامات کی پاسداری کرتے ہیں، جیسا کہ میں نے آپ کو پہنچایا۔ {آرڈیننسز: یا، روایات}\n3۔ لیکن میں چاہتا ہوں کہ آپ جان لیں کہ ہر انسان کا سر مسیح ہے؛ اور عورت کا سر {ہے} مرد ہے؛ اور مسیح کا سر خدا ہے۔\n4. ہر وہ شخص جو دعا کر رہا ہے یا نبوت کر رہا ہے، اور اس کا سر ڈھانپ کر ہے، وہ اپنے سر کی بے عزتی کرتا ہے۔\n5۔ لیکن ہر عورت جو اپنا سر بے نقاب کر کے دعا یا پیش گوئی کرتی ہے، وہ اپنے سر کی بے عزتی کرتی ہے: کیونکہ یہ سب ایسے ہی ہے جیسے وہ منڈوا دی گئی ہو۔\n6۔ اگر عورت کا لباس نہیں ہے تو اسے بھی کاٹا جائے: لیکن اگر عورت کو کاٹنا یا شیو کرنا شرم کی بات ہے تو وہ ڈھانپ دی جائے۔\n7۔ کیونکہ مرد کو واقعی اپنا سر نہیں ڈھانپنا چاہیے، کیونکہ وہ خدا کی تصویر اور جلال ہے: لیکن عورت مرد کی شان ہے۔\n8۔ کیونکہ مرد عورت کا نہیں ہے؛ لیکن مرد کی عورت۔\n9۔ نہ ہی مرد عورت کے لیے پیدا ہوا؛ لیکن عورت مرد کے لیے۔\n10۔ اس مقصد کے لیے عورت کو فرشتوں کی وجہ سے اس کے سر پر طاقت ہونی چاہیے۔ {طاقت: یہ ایک پردہ ہے کہ وہ اپنے شوہر کے زیر اثر ہے}\n11. پھر بھی نہ مرد عورت کے بغیر ہے، نہ عورت مرد کے بغیر ہے، خداوند میں۔\n12۔ کیونکہ جیسے عورت مرد کی ہے، ویسے ہی مرد بھی عورت کی وجہ سے ہے؛ لیکن خدا کی سب چیزیں۔\n13۔ اپنے آپ پر فیصلہ کریں: کیا یہ خوبصورت ہے کہ کوئی عورت خدا سے بے نقاب دعا کرے؟\n14۔ کیا قدرت خود تمہیں نہیں سکھاتی کہ اگر کسی آدمی کے لمبے بال ہوں تو یہ اس کے لیے شرم کی بات ہے؟\n15۔ لیکن اگر عورت کے بال لمبے ہوں تو یہ اس کے لیے شان ہے: کیونکہ {اس کی} بال اسے ڈھانپنے کے لیے دیے جاتے ہیں۔ {ڈھانپنا: یا، پردہ}\n16۔ لیکن اگر کوئی شخص متنازعہ نظر آتا ہے، تو ہمارے پاس ایسا کوئی رواج نہیں ہے، نہ ہی خدا کے کلیسائیں۔\n17۔ اب اس میں میں {تمہیں اعلان کرتا ہوں} میں {تمہاری} تعریف نہیں کرتا کہ تم دونوں اچھے کے لیے نہیں بلکہ برے کے لیے متحد ہو۔\n18۔ سب سے پہلے، جب تم کلیسیا میں اکٹھے ہوتے ہو، تو میں سنتا ہوں کہ تم میں اختلافات ہوتے ہیں؛ اور میں جزوی طور پر اس پر یقین رکھتا ہوں۔ {تقسیمات: یا، تقسیم}\n19۔ کیونکہ تم میں بھی بدعتیں ہونی چاہئیں، تاکہ جو منظور شدہ ہوں وہ تم میں ظاہر ہو سکیں۔ {بدعت: یا، فرقے}\n20۔ جب تم سب ایک جگہ جمع ہو جاؤ، {یہ} خداوند کا کھانا نہیں کھانا۔ {یہ...: یا، تم کھا نہیں سکتے}\n21۔ کیونکہ کھانے میں ہر کوئی اپنے کھانے سے پہلے کھاتا ہے: اور ایک بھوکا ہوتا ہے اور دوسرا نشے میں۔\n22۔ کیا؟ کیا تمہارے پاس کھانے پینے کے لیے گھر نہیں ہیں؟ یا خدا کی کلیسیا سے نفرت کرتے ہیں، اور ان لوگوں کو شرمندہ کرتے ہیں جو نہیں رہے؟ میں تم سے کیا کہوں؟ کیا میں اس میں تمہاری تعریف کروں؟ میں {تمہاری} تعریف کرتا ہوں۔ {نہیں: یا، غریب ہو؟}\n23۔ کیونکہ میں نے خداوند سے وہ سب کچھ پایا جو میں نے تمہیں دیا تھا، کہ خداوند یسوع نے اسی رات جب اسے دھوکہ دیا گیا، روٹی لے لی:\n24۔ اور جب اس نے شکر ادا کیا، تو اس نے اسے توڑا اور کہا، لو، کھاؤ: یہ میرا جسم ہے، جو تمہارے لیے ٹوٹا ہوا ہے: یہ میرے یاد میں کرو۔ {میں...: یا، یاد کے لیے}\n25۔ اسی طرح {اس نے پیالہ لیا}، جب اس نے کھانا کھایا، اور کہا، یہ پیالہ میرے خون میں نیا عہد نامہ ہے: یہ پیالہ جتنا تم پیتے ہو، میری یاد میں کرتے ہو۔\n26. کیونکہ جتنی بار تم یہ روٹی کھاتے ہو اور یہ پیالا پیتے ہو، تم خداوند کی موت دکھاتے ہو جب تک وہ نہ آ جائے۔ {تم کرتے ہو...: یا، دکھاؤ}\n27۔ اسی لیے جو بھی یہ روٹی کھائے گا اور خداوند کا یہ پیالہ نالائق ہوگا، وہ خداوند کے جسم اور خون کا مجرم ہوگا۔\n28۔ لیکن آدمی خود کو پرکھے، اور اس روٹی سے کھائے، اور اس پیالے کا پیو۔\n29۔ کیونکہ جو ناحق کھاتا اور پیتا ہے، وہ اپنے لیے لعنت کھاتا اور پیتا ہے، اور خداوند کے جسم کو پہچان نہیں پاتا۔ {لعنت: یا، فیصلہ}\n30۔ اسی وجہ سے تم میں سے بہت سے کمزور اور بیمار ہیں، اور بہت سے سو رہے ہیں۔\n31۔ کیونکہ اگر ہم خود کو پرکھیں تو ہمیں فیصلہ نہیں کیا جانا چاہیے۔\n32. لیکن جب ہمارا فیصلہ کیا جاتا ہے، تو ہمیں خداوند کی طرف سے سزا دی جاتی ہے، تاکہ ہمیں دنیا کے ساتھ ملامت نہ کیا جائے۔\n33۔ اسی لیے، میرے بھائیو، جب تم کھانے کے لیے اکٹھے ہو جاؤ، ایک دوسرے کے لیے انتظار کرو۔\n34۔ اور اگر کوئی بھوکا ہو تو گھر پر کھائے؛ کہ تم ملامت کے لیے اکٹھے نہ ہو۔ اور باقی سب میں تب ترتیب دوں گا جب میں آؤں گا۔ {مذمت: یا، فیصلہ}","1. اب روحانی {تحفات} کے بارے میں، بھائیو، میں نہیں چاہتا کہ تم جاہل ہو۔\n2۔ تم جانتے ہو کہ تم غیر یہودی تھے، جنہیں ان گونگے بتوں کی طرف لے جایا گیا، جیسے تمہیں لے جایا گیا۔\n3۔ اسی لیے میں آپ کو سمجھاتا ہوں کہ خدا کی روح سے بولنے والا کوئی بھی شخص یسوع کو نہیں کہتا: اور {کہ} کوئی بھی یہ نہیں کہہ سکتا کہ یسوع خداوند ہے، سوائے روح القدس کے۔ {لعنت: یا، لعنتی}\n4۔ نعمتوں کی مختلف اقسام ہیں، لیکن روح ایک ہی ہے۔\n5۔ اور انتظامات میں فرق ہے، لیکن ایک ہی لارڈ ہے۔ {انتظامیہ: یا، وزارتیں}\n6۔ اور مختلف اعمال ہیں، لیکن وہی خدا ہے جو سب کچھ کام کرتا ہے۔\n7۔ لیکن روح کی ظاہری شکل ہر انسان کو دی گئی ہے تاکہ وہ اس سے فائدہ اٹھائے۔\n8۔ کیونکہ روح کی طرف سے حکمت کا کلام دیا گیا ہے؛ دوسرے کے لیے اسی روح کی طرف سے علم کا کلام؛\n9۔ اسی روح کے ذریعے دوسرے ایمان کے لیے؛ دوسرے کے لیے اسی روح سے شفا کے تحفے؛\n10۔ دوسرے کے لیے معجزات کا کام؛ ایک اور پیش گوئی کی طرف؛ ایک اور روحوں کی تمیز کرنے والے؛ دوسری {مختلف} زبانوں کے لیے؛ دوسرے کے لیے زبانوں کی تشریح:\n11۔ لیکن یہ سب ایک ہی روح کو کام کرتے ہیں، جو ہر انسان کو الگ الگ تقسیم کرتا ہے۔\n12۔ جیسے جسم ایک ہے، اور اس کے کئی ارکان ہیں، اور اس ایک جسم کے تمام ارکان، جو کئی ہیں، ایک جسم ہیں: اسی طرح مسیح بھی ہے۔\n13۔ کیونکہ ایک روح کے ذریعے ہم سب ایک جسم میں بپتسمہ پائے جاتے ہیں، چاہے ہم یہودی ہوں یا غیر یہودی، چاہے ہم بندھن ہوں یا آزاد؛ اور سب کو ایک روح میں پینے پر مجبور کیا گیا ہے۔ {غیر یہودی: یونانی یونانی}\n14۔ کیونکہ جسم ایک رکن نہیں بلکہ کئی افراد پر مشتمل ہے۔\n15۔ اگر پاؤں کہے، چونکہ میں ہاتھ نہیں ہوں، میں جسم کا نہیں ہوں؛ تو کیا یہ جسم کا نہیں ہے؟\n16۔ اور اگر کان کہے، کیونکہ میں آنکھ نہیں ہوں، میں جسم کا نہیں ہوں؛ تو کیا یہ جسم کا نہیں ہے؟\n17. اگر پورا جسم ایک آنکھ تھا، تو سماعت کہاں تھی؟ اگر پوری سماعت تھی، تو وہ خوشبو کہاں تھی؟\n18۔ لیکن اب خدا نے ان میں سے ہر ایک کو جسم میں شامل کیا ہے، جیسا کہ اس نے چاہا۔\n19۔ اور اگر وہ سب ایک رکن تھے، تو لاش کہاں تھی؟\n20۔ لیکن اب {کیا وہ} بہت سے ارکان ہیں، پھر بھی صرف ایک جسم۔\n21. اور آنکھ ہاتھ سے نہیں کہہ سکتی، مجھے تمہاری ضرورت نہیں؛ اور پھر سر سے پاؤں تک، مجھے تمہاری ضرورت نہیں۔\n22۔ بلکہ، جسم کے وہ ارکان، جو زیادہ کمزور نظر آتے ہیں، بہت زیادہ ضروری ہیں:\n23۔ اور وہ {ارکان} جو جسم کے کم معزز سمجھتے ہیں، ان کو ہم زیادہ عزت دیتے ہیں؛ اور ہمارے ناپسندیدہ حصے زیادہ خوبصورتی رکھتے ہیں۔ {عطا کریں: یا، پہنیں}\n24۔ کیونکہ ہمارے خوبصورت حصوں کی ضرورت نہیں: لیکن خدا نے جسم کو مضبوط کیا ہے، اور اس حصے کو زیادہ عزت دی ہے جس میں کمی تھی:\n25۔ کہ جسم میں کوئی تقسیم نہیں ہونی چاہیے؛ لیکن {یہ} کہ اراکین کو ایک دوسرے کے لیے یکساں خیال رکھنا چاہیے۔ {تقسیم: یا، تقسیم}\n26۔ اور اگر ایک رکن تکلیف اٹھائے، تو تمام افراد اس کے ساتھ تکلیف اٹھاتے ہیں؛ یا ایک رکن کو عزت دی جائے، تمام ارکان اس پر خوش ہوں۔\n27. اب تم مسیح کے جسم ہو، خاص طور پر اس کے ارکان کا۔\n28۔ اور خدا نے کلیسیا میں کچھ مقرر کیے ہیں، پہلے رسول، بعد میں نبی، تیسرے استاد، پھر معجزات، پھر شفا، مدد، حکومتیں، زبانوں کی تنوع۔ {تنوعات: یا، اقسام}\n29۔ کیا سب رسول ہیں؟ کیا سب نبی ہیں؟ {کیا} سب اساتذہ ہیں؟ کیا یہ سب معجزے کرنے والے ہیں؟ {کارکن...: یا، طاقتیں؟}\n30۔ کیا آپ کے پاس شفا کے تمام تحفے ہیں؟ کیا سب زبانوں سے بات کرتے ہیں؟ کیا سب تشریح کرتے ہیں؟\n31. لیکن دل سے بہترین تحفوں کی خواہش کرو: اور پھر بھی میں تمہیں اس سے بھی بہتر راستہ دکھاتا ہوں۔","1۔ اگرچہ میں انسانوں اور فرشتوں کی زبانوں سے بات کرتا ہوں اور محبت نہیں کرتا، میں {جیسے} پیتل کی آواز یا جھنجھناتا ہوا بن چکا ہوں۔\n2۔ اور اگرچہ میرے پاس پیش گوئی کا تحفہ ہے، اور میں تمام راز اور علم کو سمجھتا ہوں؛ اور اگرچہ میں مکمل ایمان رکھتا ہوں، تاکہ میں پہاڑ ہٹا سکوں، اور محبت نہ کروں، میں کچھ بھی نہیں ہوں۔\n3۔ اور اگرچہ میں اپنی ساری دولت غریبوں کو کھلانے کے لیے دیتا ہوں، اور اگرچہ میں اپنا جسم جلانے کے لیے دیتا ہوں، اور خیرات نہیں کرتا، تو اس سے مجھے کوئی فائدہ نہیں۔\n4۔ محبت طویل عرصے تک تکلیف میں رہتی ہے، {اور} مہربان ہے؛ خیرات حسد نہیں کرتی؛ خیرات خود کو ظاہر نہیں کرتی، نہ ہی بڑھا چڑھا کر پیش کی جاتی ہے، {فخر سے...: یا، جلد بازی نہیں ہے}\n5۔ کیا وہ خود کو بدتمیز نہیں کرتا، اپنی مرضی کی تلاش نہیں کرتا، آسانی سے مشتعل نہیں ہوتا، برائی نہیں سوچتا؛\n6۔ بدکاری پر خوش نہ ہو، بلکہ سچائی پر خوش ہو؛ {سچ میں: یا، سچائی کے ساتھ}\n7۔ سب کچھ برداشت کرتا ہے، سب پر ایمان رکھتا ہے، سب کچھ امید رکھتا ہے، سب کچھ برداشت کرتا ہے۔\n8۔ محبت کبھی ناکام نہیں ہوتی: لیکن اگر پیش گوئیاں ہوں تو وہ ناکام ہو جائیں گی؛ چاہے زبانیں ہوں، وہ رک جائیں گی؛ چاہے کوئی علم ہو، وہ ختم ہو جائے گا۔ {ناکامی: Gr. غائب ہو جاؤ}\n9۔ کیونکہ ہم جزوی طور پر جانتے ہیں، اور جزوی طور پر پیش گوئی کرتے ہیں۔\n10۔ لیکن جب کامل چیز آ جائے، تو جو کچھ جزوی ہے وہ ختم ہو جائے گا۔ {ختم ہو گیا: Gr. vanish away}\n11۔ جب میں بچہ تھا، میں بچپن میں بولتا تھا، بچپن میں سمجھتا تھا، بچپن میں سوچتا تھا: لیکن جب میں مرد بنا، تو بچگانہ باتیں چھوڑ دیں۔ {سوچا: یا، دلیل} {بند کر دیں: Gr. vanish away}\n12۔ فی الحال ہم شیشے کے پار دیکھتے ہیں، تاریک انداز میں؛ لیکن پھر آمنے سامنے: اب میں جزوی طور پر جانتا ہوں؛ لیکن پھر میں جانوں گا جیسا کہ مجھے جانا جاتا ہے۔ {گہرے لہجے میں: Gr. ایک پہیلی میں}\n13۔ اور اب ایمان، امید، محبت یہ تینوں قائم ہیں؛ لیکن ان میں سب سے بڑا {ہے} خیرات ہے۔","1۔ محبت کی پیروی کرو، اور روحانی تحفے کی خواہش کرو، بلکہ اس لیے کہ تم نبوت کر سکو۔\n2۔ کیونکہ جو کوئی {نامعلوم} زبان میں بولتا ہے وہ انسانوں سے نہیں بلکہ خدا سے بات کرتا ہے: کیونکہ کوئی انسان اسے نہیں سمجھتا؛ تاہم، وہ روح کے ساتھ اسرار بولتے ہیں۔ {سمجھتا ہے: Gr. heareth}\n3۔ لیکن جو پیش گوئی کرتا ہے وہ انسانوں سے تعلیم، نصیحت اور تسلی کے لیے بات کرتا ہے۔\n4۔ جو شخص ایک {نامعلوم} زبان میں بولتا ہے وہ خود کو تعلیم دیتا ہے؛ لیکن جو نبوت کرتا ہے وہ کلیسیا کی بنیاد رکھتا ہے۔\n5۔ میں چاہتا ہوں کہ آپ سب زبانوں سے بات کریں، بلکہ آپ نے پیش گوئی کی ہو: کیونکہ جو پیش گوئی کرتا ہے وہ زبانوں سے بولنے والے سے زیادہ عظیم ہے، سوائے اس کے کہ وہ تشریح کرے، تاکہ کلیسیا کو احیاء ملے۔\n6۔ اب، بھائیو، اگر میں آپ کے پاس زبانوں سے بات کر رہا ہوں، تو آپ کو کیا فائدہ ہوگا، سوائے اس کے کہ میں آپ سے یا تو وحی کے ذریعے، یا علم سے، یا نبوت کے ذریعے، یا عقیدے سے بات کروں؟\n7۔ اور یہاں تک کہ وہ چیزیں جن میں زندگی بخش آواز نہ ہو، چاہے پائپ ہو یا ہارپ، جب تک کہ وہ آوازوں میں فرق نہ کریں، یہ کیسے معلوم ہوگا کہ پائپ کیا جاتا ہے اور کیا ہارپ؟ {آوازیں: یا، دھنیں}\n8۔ اگر ترمپٹ غیر یقینی آواز دے تو کون خود کو جنگ کے لیے تیار کرے گا؟\n9. اسی طرح، جب تک آپ زبان سے آسان الفاظ نہ بولیں، کیسے معلوم ہوگا کہ کیا کہا جاتا ہے؟ کیونکہ تم ہوا میں بولو گے۔ {آسان...: Gr. significance}\n10. دنیا میں اتنی ساری آوازیں ہو سکتی ہیں، اور ان میں سے کوئی بھی بغیر معنی کے نہیں ہے۔\n11۔ لہٰذا اگر میں آواز کا مطلب نہیں جانتا، تو میں اس کے لیے وحشی ہوں گا جو بولتا ہے، اور جو بولے گا وہ میرے لیے وحشی ہوگا۔\n12۔ اسی طرح، جب تک آپ روحانی نعمتوں کے لیے پرجوش ہیں، کلیسیا کی تعمیر میں کامیاب ہونے کی کوشش کرتے ہیں۔ {روحانی تحفوں کی: ارواح کی گروہ}\n13۔ لہٰذا جو کوئی {نامعلوم} زبان بولتا ہے وہ دعا کرے کہ وہ تشریح کر سکے۔\n14۔ کیونکہ اگر میں کسی {نامعلوم} زبان میں دعا کروں تو میری روح دعا کرتی ہے، لیکن میری سمجھ بے نتیجہ ہے۔\n15. تو پھر کیا ہے؟ میں روح کے ساتھ دعا کروں گا، اور سمجھ بوجھ کے ساتھ بھی: میں روح کے ساتھ گاؤں گا، اور سمجھ بوجھ کے ساتھ بھی۔\n16۔ ورنہ جب تم روح سے برکت دو گے، تو جو نامعلوم کے کمرے میں بیٹھا ہے وہ تمہارے شکر گزاری پر آمین کیسے کہے گا، جب کہ وہ تمہاری بات نہیں سمجھتا؟\n17۔ کیونکہ تم واقعی شکر گزار ہو، لیکن دوسرا نہیں،\n18۔ میں اپنے خدا کا شکر ادا کرتا ہوں، میں تم سب سے زیادہ زبانوں سے بات کرتا ہوں:\n19۔ پھر بھی چرچ میں میں نے پانچ الفاظ اپنی سمجھ بوجھ کے ساتھ بولنا پسند کیا، تاکہ {اپنی آواز سے} دوسروں کو بھی سکھا سکوں، بجائے اس کے کہ ایک {نامعلوم} زبان میں دس ہزار الفاظ بولوں۔\n20. بھائیو، سمجھ بوجھ میں بچے نہ بنو: چاہے تم بچے بغض میں ہو، بلکہ سمجھ میں انسان ہوں۔ {مرد: گریڈ پرفیکٹ، یا، ایک پختہ عمر کا}\n21۔ شریعت میں لکھا ہے، {دیگر زبانوں اور زبانوں کے لوگ} سے میں اس قوم سے بات کروں گا؛ اور پھر بھی، چاہے وہ میری بات نہ سنیں، خداوند فرماتا ہے۔\n22۔ لہٰذا زبانیں ایک علامت ہیں، نہ کہ ان کے لیے جو ایمان لاتے ہیں، بلکہ ان کے لیے جو ایمان نہیں لاتے ہیں، بلکہ ان کے لیے جو ایمان نہیں لاتے ہیں، بلکہ ان کے لیے پیش گوئی کرتی ہیں جو ایمان نہیں رکھتے۔\n23۔ لہٰذا اگر پوری کلیسیا ایک جگہ جمع ہو جائے، اور سب زبانوں سے بات کریں، اور وہاں {جو لوگ} غیر تعلیم یافتہ یا کافر ہیں، آ جائیں، تو کیا وہ نہیں کہیں گے کہ تم پاگل ہو؟\n24. لیکن اگر تمام نبوتیں، اور کوئی ایسا ہو جو ایمان نہ رکھتا ہو، یا {ایک} ناعلم ہو، وہ سب پر قائل ہو تو وہ سب کا فیصلہ کیا جاتا ہے:\n25۔ اور یوں اس کے دل کے راز ظاہر ہوتے ہیں؛ اور یوں وہ اپنے چہرے پر گر کر خدا کی عبادت کرے گا، اور رپورٹ کرے گا کہ خدا آپ میں ایک سچائی ہے۔\n26۔ تو پھر کیسا ہے، بھائیو؟ جب تم سب اکٹھے ہو جاؤ، تو تم میں سے ہر ایک کے پاس زبور، تعلیم، زبان، وہی اور تشریح ہوتی ہے۔ آئیے سب کچھ تعلیم کے لیے کیا جائے۔\n27۔ اگر کوئی شخص {نامعلوم} زبان میں بولے، تو {اسے دو سے} یا زیادہ سے زیادہ {تین} سے، اور {وہ} کورس سے؛ اور کسی کو تشریح کرنے دیں۔ {دو...: دو یا تین جملوں میں الگ الگ}\n28۔ لیکن اگر مترجم نہ ہو تو وہ چرچ میں خاموش رہے؛ اور اسے اپنے آپ سے اور خدا سے بات کرنے دو۔\n29۔ نبیوں کو دو یا تین بولنے دو، اور دوسرا فیصلہ کرے۔\n30۔ اگر {کوئی چیز} کسی اور پر ظاہر ہو جائے جو بیٹھا ہے، تو پہلا خاموش رہے۔\n31۔ کیونکہ تم سب ایک ایک کر کے پیش گوئی کرو، تاکہ سب سیکھیں اور سب کو تسلی ملے۔\n32۔ اور انبیاء کی روحیں انبیاء کے تابع ہیں۔\n33۔ کیونکہ خدا الجھن کا خالق نہیں، بلکہ امن کا ہے، جیسا کہ تمام مقدسین کی کلیساؤں میں ہوتا ہے۔ {الجھن: Gr. ہلچل، یا، بے چینی}\n34۔ تمہاری عورتیں کلیساؤں میں خاموش رہیں: کیونکہ انہیں بولنے کی اجازت نہیں؛ لیکن {انہیں حکم دیا گیا ہے} کہ وہ اطاعت کریں، جیسا کہ قانون بھی کہتا ہے۔\n35۔ اور اگر وہ کچھ سیکھنا چاہیں تو اپنے گھر پر اپنے شوہروں سے پوچھیں: کیونکہ چرچ میں عورتوں کے لیے بات کرنا شرم کی بات ہے۔\n36۔ کیا؟ کیا خدا کا کلام تم سے نکلا؟ یا یہ صرف تمہیں ملی؟\n37۔ اگر کوئی شخص خود کو نبی یا روحانی سمجھتا ہے، تو وہ تسلیم کرے کہ جو چیزیں میں آپ کے لیے لکھ رہا ہوں وہ خداوند کے احکامات ہیں۔\n38۔ لیکن اگر کوئی شخص جاہل ہے تو وہ جاہل ہو۔\n39۔ اسی لیے، بھائیو، نبوت کی خواہش کرو، اور زبانوں سے بات نہ کرنے سے منع کرو۔\n40۔ سب کچھ شائستگی اور ترتیب سے کیا جائے۔","1۔ مزید برآں، بھائیو، میں آپ کو وہ خوشخبری دیتا ہوں جو میں نے آپ کو سنایا، جو آپ کو بھی ملی ہے، اور جس میں آپ کھڑے ہیں؛\n2۔ جس کے ذریعے تم بھی نجات پاتے ہو، اگر تم وہ سب یاد رکھو جو میں نے تمہیں بتایا ہے، جب تک کہ تم نے بے سود ایمان نہ رکھا ہو۔ {رکھو...: یا، مضبوطی سے پکڑے رہو} {کیا: Gr. کس تقریر کے ذریعے}\n3۔ کیونکہ میں نے سب سے پہلے تمہیں وہ سب سے پہلے پہنچایا جو مجھے بھی ملا، کہ وہ مسیح ہمارے گناہوں کے لیے مرا جیسا کہ صحیفہ کے مطابق ہے؛\n4۔ اور کہ اسے دفن کیا گیا، اور وہ تیسرے دن صحیفوں کے مطابق دوبارہ زندہ ہوا:\n5۔ اور وہ کیفاس کے بارے میں دیکھا گیا، پھر بارہ میں سے:\n6۔ اس کے بعد، اسے ایک ساتھ پانچ سو سے زائد بھائیوں میں دیکھا گیا؛ جن میں سے زیادہ تر آج تک موجود ہیں، لیکن کچھ سو چکے ہیں۔\n7۔ اس کے بعد، اسے جیمز کے پاس دیکھا گیا؛ پھر تمام رسولوں میں سے۔\n8۔ اور آخر میں، وہ مجھے بھی دیکھا گیا، جیسے وقت کے بعد پیدا ہوا ہو۔ {ایک...: یا، ایک ناکام}\n9۔ کیونکہ میں رسولوں میں سب سے چھوٹا ہوں، جو رسول کہلانے کے قابل نہیں، کیونکہ میں نے خدا کی کلیسیا کو ستایا۔\n10۔ لیکن خدا کے فضل سے میں وہی ہوں جو ہوں: اور اس کا فضل جو {مجھے دیا گیا} رائیگاں نہیں گیا؛ لیکن میں نے ان سب سے زیادہ محنت کی: پھر بھی میں نہیں، بلکہ خدا کا فضل جو میرے ساتھ تھا۔\n11. لہٰذا چاہے میں ہوں یا وہ، ہم یہی تبلیغ کرتے ہیں، اور تم نے ایمان لیا۔\n12۔ اب اگر مسیح کو وعظ کیا جائے کہ وہ مردوں میں سے زندہ ہوا، تو تم میں سے کچھ لوگ کیسے کہیں گے کہ مردوں کی قیامت نہیں ہوتی؟\n13۔ لیکن اگر مردوں کی قیامت نہ ہو، تو کیا مسیح زندہ نہیں ہوا:\n14۔ اور اگر مسیح زندہ نہ ہو، تو ہماری تبلیغ فضول ہے، اور تمہارا ایمان بھی بے کار ہے۔\n15۔ ہاں، اور ہم خدا کے جھوٹے گواہ پائے جاتے ہیں؛ کیونکہ ہم نے خدا کی گواہی دی ہے کہ اس نے مسیح کو زندہ کیا: جسے اس نے زندہ نہیں کیا، اگر ایسا ہو کہ مردہ نہ اٹھیں۔\n16. کیونکہ اگر مردے نہیں اٹھتے، تو مسیح زندہ نہیں ہوتا:\n17۔ اور اگر مسیح زندہ نہ ہوا تو تمہارا ایمان بے کار ہے؛ تم ابھی بھی اپنے گناہوں میں ہو۔\n18۔ پھر وہ بھی جو مسیح میں سوئے ہوئے ہیں، ہلاک ہو جاتے ہیں۔\n19۔ اگر اس زندگی میں صرف ہمیں مسیح پر امید ہے، تو ہم سب میں سب سے زیادہ بدحال ہیں۔\n20. لیکن اب مسیح مردوں میں سے زندہ ہو چکا ہے، {اور} ان کے پہلے پھل بن گیا ہے جو سویا تھا۔\n21۔ کیونکہ چونکہ انسان کی وجہ سے {آی} موت، انسان کے ذریعے مردوں کی دوبارہ زندہ بھی ہوئی۔\n22۔ جیسے آدم میں سب مرتے ہیں، اسی طرح مسیح میں سب زندہ ہوں گے۔\n23۔ لیکن ہر شخص اپنی ترتیب میں: مسیح پہلا پھل؛ اس کے بعد وہ لوگ جو مسیح کے آتے ہیں۔\n24۔ پھر {آتا ہے} جب وہ بادشاہی خدا کے حوالے کر دے گا، حتیٰ کہ باپ کو بھی؛ جب وہ تمام حکمرانی، تمام اختیار اور طاقت کو ختم کر دے گا۔\n25۔ کیونکہ اسے حکومت کرنی ہوگی، جب تک کہ وہ تمام دشمنوں کو اپنے قدموں تلے نہ رکھ دے۔\n26. آخری دشمن {جو} تباہ ہوگا {وہ ہے} موت۔\n27۔ کیونکہ اس نے سب کچھ اپنے قدموں تلے رکھ دیا ہے۔ لیکن جب وہ کہتا ہے کہ تمام چیزیں {اس کے ماتحت' ہیں، تو یہ ظاہر ہوتا ہے کہ وہ مستثنیٰ ہے، جس نے سب کچھ اس کے نیچے کر دیا۔\n28۔ اور جب سب کچھ اس کے تابع ہو جائے گا، تو بیٹا خود بھی اس کے تابع ہوگا جس نے سب کچھ اس کے تحت رکھا ہے، تاکہ خدا سب کچھ ہو۔\n29۔ ورنہ وہ کیا کریں گے جو مردوں کے لیے بپتسمہ لیتے ہیں، اگر مردے زندہ ہی نہ ہوں؟ پھر وہ مردوں کے لیے کیوں بپتسمہ لیے جاتے ہیں؟\n30۔ اور ہم ہر گھنٹے خطرے میں کیوں کھڑے ہیں؟\n31. میں آپ کی خوشی سے احتجاج کرتا ہوں جو مجھے مسیح یسوع ہمارے رب میں ہے، میں روزانہ مرتا ہوں۔ {تمہارا: کچھ پڑھیں، ہماری}\n32۔ اگر میں نے افسس میں انسانوں کی طرح جانوروں سے لڑائی کی، تو اگر مردہ نہ اٹھیں تو مجھے کیا فائدہ ہے؟ آؤ کھائیں اور پیئیں؛ کیونکہ کل ہم مر جائیں گے۔ {بعد...: یا، انسانوں کے انداز کے مطابق بولنا}\n33۔ دھوکہ نہ کھائیں: برائی کی بات چیت اچھے آداب کو خراب کرتی ہے۔\n34۔ راستبازی کے لیے جاگ جاؤ، اور گناہ نہ کرو؛ کیونکہ کچھ لوگوں کو خدا کا علم نہیں: میں یہ بات تمہاری شرمندگی کے لیے کہتا ہوں۔\n35۔ لیکن کچھ {مرد} کہیں گے، مردوں کو کیسے زندہ کیا جاتا ہے؟ اور وہ کس جسم کے ساتھ آتے ہیں؟\n36۔ {تو} بیوقوف، جو کچھ تم بوتا ہے وہ زندہ نہیں ہوتا، سوائے اس کے کہ وہ مر جائے:\n37۔ اور جو تم بوتے ہو، وہ جسم نہیں بوتے جو صرف اناج کے بغیر گندم یا کسی اور اناج کا ہو سکتا ہے:\n38۔ لیکن خدا اسے ایک جسم دیتا ہے جیسا اس نے اسے پسند کیا، اور ہر بیج کو اپنا جسم دیتا ہے۔\n39۔ تمام گوشت {ہے} ایک ہی گوشت نہیں ہے: لیکن {انسانوں کا} ایک {قسم} گوشت ہے، دوسرا جانوروں کا گوشت، ایک اور مچھلیوں کا، {اور} پرندوں کا دوسرا گوشت ہے۔\n40۔ {کچھ آسمانی اجسام بھی ہیں}، اور زمینی اجسام بھی ہیں: لیکن آسمانی جلال {ہے} ایک، اور زمینی {جلال} ایک اور۔\n41. {سورج کی ایک شان ہے}، چاند کی ایک اور شان، اور ستاروں کی ایک اور شان: کیونکہ {ایک} ستارہ جلال میں {دوسری} ستارے سے مختلف ہے۔\n42. اسی طرح مردوں کی قیامت بھی ہے۔ یہ کرپشن میں بویا گیا ہے؛ یہ انکرپشن میں پروان چڑھا ہے:\n43۔ یہ بے عزتی میں بویا جاتا ہے؛ یہ جلال میں پالا جاتا ہے: کمزوری میں بویا جاتا ہے؛ یہ اقتدار میں اٹھایا جاتا ہے:\n44۔ اسے قدرتی جسم کے طور پر بویا جاتا ہے؛ یہ ایک روحانی جسم کی طرح اٹھایا جاتا ہے۔ ایک قدرتی جسم ہے، اور ایک روحانی جسم ہے۔\n45۔ اور یوں لکھا ہے، پہلا آدمی آدم زندہ روح بنا؛ آخری آدم {بنایا گیا} ایک تیز روح تھا۔\n46۔ تاہم وہ {تھا} پہلا نہیں جو روحانی ہے، بلکہ جو قدرتی ہے؛ اور اس کے بعد روحانی چیزیں۔\n47۔ پہلا انسان زمین کا {ہے}، زمینی ہے: دوسرا انسان {ہے} آسمان سے خداوند ہے۔\n48. جیسے {ہے} زمینی، ایسے بھی ہیں جو زمینی ہیں؛ اور جیسے {ہے} آسمانی، ایسے بھی ہیں جو آسمانی ہیں۔\n49۔ اور جیسے ہم نے زمینی کی تصویر رکھی ہے، ویسے ہی ہم آسمانی کی تصویر بھی اٹھائیں گے۔\n50۔ اب میں یہ کہتا ہوں، بھائیو، کہ گوشت اور خون خدا کی بادشاہی کا وارث نہیں بن سکتے؛ بدعنوانی بھی بدعنوانی کو وراثت میں نہیں ملتی۔\n51. دیکھو، میں تمہیں ایک راز دکھاتا ہوں؛ ہم سب نہیں سوئیں گے، لیکن ہم سب بدل جائیں گے،\n52. ایک لمحے میں، ایک پلک جھپکنے میں، آخری ٹرمپ پر: کیونکہ بگل بجے گا، اور مردے بے فساد زندہ ہوں گے، اور ہم بدل جائیں گے۔\n53۔ کیونکہ اس بدعنوان کو بدعنوانی پہننی ہوگی، اور یہ فانی {لازم} امر ہونا چاہیے۔\n54. تو جب یہ بدعنوان شخص بدعنوانی پہن لے گا، اور یہ فانی امر ہو جائے گا، تو پھر وہ کہاوت حقیقت میں آئے گی جو لکھا گیا ہے، موت فتح میں نگل لی جاتی ہے۔\n55۔ اے موت، تیری ڈنک کہاں ہے؟ اے قبر، تمہاری فتح کہاں ہے؟ {قبر: یا، جہنم}\n56۔ موت کا ڈنک {ہے} گناہ ہے؛ اور گناہ کی طاقت قانون ہے۔\n57. بلکہ خدا کا شکر ادا کریں، جو ہمیں ہمارے رب یسوع مسیح کے ذریعے فتح دیتا ہے۔\n58۔ لہٰذا، میرے پیارے بھائیو، تم ثابت قدم رہو، ثابت قدم رہو، ہمیشہ خداوند کے کام میں سرشار رہو، کیونکہ تم جانتے ہو کہ تمہاری محنت خداوند میں رائیگاں نہیں گئی۔","1۔ اب مقدسین کے لیے جمع کرنے کے بارے میں، جیسا کہ میں نے گلاطیہ کی کلیساؤں کو ترتیب دیا ہے، تم بھی ایسا ہی کرتے ہو۔\n2۔ ہفتے کے پہلے دن تم سب اس کے پاس لیٹ جاؤ، جیسا کہ خدا نے اسے خوش کیا ہے، تاکہ جب میں آؤں تو کوئی اجتماع نہ ہو۔\n3۔ اور جب میں آؤں گا، جسے تم اپنے خطوط سے منظور کرو گے، میں اسے تمہاری سخاوت یروشلم لانے کے لیے بھیجوں گا۔ {لبرلٹی: گریڈ گفٹ}\n4۔ اور اگر میں بھی جاؤں تو وہ میرے ساتھ جائیں گے۔\n5. اب میں تمہارے پاس آؤں گا، جب میں مقدونیہ سے گزروں گا: کیونکہ میں مقدونیہ سے گزرتا ہوں۔\n6۔ اور یہ بھی ہو سکتا ہے کہ میں تمہارے ساتھ رہوں، ہاں، اور سردیوں میں گزاروں، تاکہ تم مجھے میرے سفر پر لے جاؤ۔\n7۔ کیونکہ میں تمہیں اب نہیں دیکھوں گا؛ لیکن میں امید کرتا ہوں کہ اگر خدا اجازت دے تو میں آپ کے ساتھ کچھ دیر رک سکتا ہوں۔\n8۔ لیکن میں پنٹیکوسٹ تک ایفسس میں رہوں گا۔\n9۔ کیونکہ میرے لیے ایک عظیم اور مؤثر دروازہ کھل گیا ہے، اور {بہت سے دشمن} ہیں۔\n10۔ اب اگر تیموتھیئس آئے، تو دیکھو کہ وہ تمہارے ساتھ بغیر خوف کے رہے: کیونکہ وہ خداوند کا کام کرتا ہے، جیسا کہ میں بھی کرتا ہوں۔\n11۔ لہٰذا کوئی اسے حقیر نہ سمجھے، بلکہ اسے امن کے ساتھ باہر لے چلو، تاکہ وہ میرے پاس آ سکے: کیونکہ میں اسے بھائیوں کے ساتھ تلاش کرتا ہوں۔\n12۔ ہمارے بھائی اپولس کے حوالے سے، میں نے بہت خواہش کی کہ وہ بھائیوں کے ساتھ آپ کے پاس آئیں: لیکن اس وقت اس کی مرضی بالکل نہیں تھی؛ لیکن وہ اس وقت آئے گا جب اسے مناسب وقت ملے گا۔\n13۔ دیکھو، ایمان میں مضبوطی سے کھڑے رہو، مردوں کی طرح چھوڑ دو، مضبوط رہو۔\n14۔ اپنی تمام چیزیں خیرات کے ساتھ کریں۔\n15. میں آپ سے التجا کرتا ہوں، بھائیو، (آپ اسٹیفناس کے گھر کو جانتے ہیں، کہ یہ آخایا کے پہلے پھل ہیں، اور {کہ} وہ مقدسین کی خدمت کے عادی ہو گئے ہیں،)\n16۔ کہ آپ خود کو اس کے سامنے سر تسلیم خم کریں، اور ہر اس شخص کے سامنے جو ہماری مدد کرتا ہے اور محنت کرتا ہے۔\n17. میں اسٹیفاناس، فورچوناٹس اور اکائیکس کے آنے پر خوش ہوں: جو کچھ آپ کی طرف سے کمی تھی اس کے لیے انہوں نے فراہم کی۔\n18۔ کیونکہ انہوں نے میری روح اور تمہاری روح کو تازہ کر دیا ہے: اس لیے ایسے لوگوں کو تسلیم کرو۔\n19۔ ایشیا کے گرجا گھر آپ کو سلام پیش کرتے ہیں۔ ایکویلا اور پریسیلا آپ کو خداوند میں بہت سلام کرتی ہیں، اس چرچ کے ساتھ جو ان کے گھر میں ہے۔\n20۔ تمام بھائی آپ کو سلام کرتے ہیں۔ ایک دوسرے کو مقدس بوسے سے سلام کرو۔\n21. میرے ہاتھ سے {مجھے} پولس کا سلام۔\n22۔ اگر کوئی شخص خداوند یسوع مسیح سے محبت نہیں کرتا، تو وہ انتیما ماراناتھا ہو۔\n23. ہمارے رب یسوع مسیح کا فضل آپ کے ساتھ ہو۔\n24. میری محبت تم سب کے ساتھ مسیح یسوع میں ہو۔ آمین۔ «{کرنتھیوں کو پہلا خط} فلپی سے اسٹیفاناس، فورچوناٹس، اخائیکس اور تیموتھیئس نے لکھا تھا۔}»"];
